                writer.WriteString("project", serverDetail.Project);

            if (serverDetail.SshPubKeyOption.IsSet)
                writer.WriteString("ssh_pub_key", serverDetail.SshPubKey);

            if (serverDetail.BootIso != null)
                writer.WriteString("boot_iso", serverDetail.BootIso);
            else
                writer.WriteNull("boot_iso");
        }
    }
}
